def generate(rng):
    k_val = rng.randint(2, 50)
    alpha_pct = rng.choice([20, 25, 30, 33, 40, 50])
    opts = [
        {
            "content": "La función intensiva $\\phi(k) \\equiv Q/L$ mide el producto por trabajador (producto medio del trabajo), mientras que su primera derivada $\\phi'(k)$ mide el producto marginal del capital $f_K$.",
            "is_correct": True,
            "distractor_id": None
        },
        {
            "content": "El valor de $\\phi(k)$ representa directamente el producto marginal del capital, mientras que $\\phi'(k)$ expresa el producto total de la economía.",
            "is_correct": False,
            "distractor_id": "D-C02-01",
            "error_rationale": "La función $\\phi(k) \\equiv Q/L$ es el producto medio del trabajo (producto por trabajador), no el producto marginal del capital. El producto marginal del capital está dado por su derivada $\\phi'(k) = f_K$."
        },
        {
            "content": "Puesto que $f(K,L)$ presenta rendimientos constantes a escala, cada insumo individual debe exhibir rendimientos marginales constantes, de modo que $\\phi''(k) = 0$.",
            "is_correct": False,
            "distractor_id": "D-C02-02",
            "error_rationale": "Los rendimientos constantes a escala conviven con rendimientos marginales decrecientes en cada factor individual ($f_{KK} < 0$), lo que garantiza $\\phi''(k) < 0$."
        },
        {
            "content": "En virtud de la homogeneidad de grado 1, la función de producción agregada puede expresarse de forma intensiva per cápita dependiendo únicamente de $k = K/L$.",
            "is_correct": True,
            "distractor_id": None
        }
    ]
    return {
        'vars': {'k_val': k_val, 'alpha_pct': alpha_pct},
        'options': opts,
        'distractors': []
    }

